defense.vulnerable_config:
# Vulnerable LDAP filter (PHP)
$filter = "(&(uid=" . $_POST['username'] . ")(userPassword=" . $_POST['password'] . "))";
// POST username=* password=* -> matches all users

defense.secure_config:
# Escape LDAP metacharacters (RFC 4515)
function ldap_escape_filter($str) {
  $chars = ['\\', '*', '(', ')', "\x00"];
  $esc = ['\\5c', '\\2a', '\\28', '\\29', '\\00'];
  return str_replace($chars, $esc, $str);
}
$filter = '(&(uid=' . ldap_escape_filter($_POST['username']) .
           ')(userPassword=' . ldap_escape_filter($_POST['password']) . '))';
# Or use ldap_bind() with user DN directly
